import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;

// Scene durations
const SCENE_HEADER = 32;
const SCENE_CODE = 80;
const SCENE_OUTRO = 28;

export const durationInFrames =
  SCENE_HEADER + TRANSITION + SCENE_CODE + TRANSITION + SCENE_OUTRO;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ============================================================
// SCENE 1 — Headline intro
// ============================================================
const HeaderScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();
  const base = width;

  const titleIn = springIn(frame, vfps, 2, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 8, "LIQUID");
  const subIn = springIn(frame, vfps, 14, "GENTLE");
  const eyebrowIn = springIn(frame, vfps, 0, "GENTLE");

  const driftY = ambientDrift(frame, 3, 90, "header-y");
  const driftX = ambientDrift(frame, 2, 110, "header-x");

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg }}>
      <Background />

      {/* Off-center anchored hero */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "32%",
          maxWidth: "78%",
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.textSubtle,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            marginBottom: base * 0.028,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
          }}
        >
          mcpc · x402 · wallet
        </div>

        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: base * 0.092,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.02,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [40, 0])}px) scale(${interpolate(titleIn, [0, 1], [0.94, 1])})`,
            filter: `blur(${interpolate(titleIn, [0, 1], [8, 0])}px)`,
          }}
        >
          Spin up a{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(3, base * 0.0035)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.014}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            crypto wallet
          </span>
          <br />
          in three commands.
        </div>

        {/* Subhead */}
        <div
          style={{
            marginTop: base * 0.032,
            fontFamily: "Inter, sans-serif",
            fontWeight: 500,
            fontSize: base * 0.028,
            color: COLORS.textMuted,
            lineHeight: 1.35,
            maxWidth: base * 0.55,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
          }}
        >
          One CLI. Local key, imported key, instant verify.
        </div>
      </div>

      {/* Subtle bottom-corner dotted band — Apify motif */}
      <div
        style={{
          position: "absolute",
          right: "-10%",
          bottom: "-10%",
          width: "60%",
          height: "40%",
          background: `radial-gradient(circle at 50% 50%, ${COLORS.orange} 0.6px, transparent 1px)`,
          backgroundSize: "22px 22px",
          opacity: 0.18,
          mixBlendMode: "screen",
          filter: "blur(0.5px)",
        }}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 2 — Code reveal (the meat)
// ============================================================

type CommandBlock = {
  comment: string;
  command: string;
  arg?: string;
};

const COMMANDS: CommandBlock[] = [
  {
    comment: "# Create a new wallet (generates a random private key)",
    command: "mcpc x402 init",
  },
  {
    comment: "# Or import an existing wallet from a private key",
    command: "mcpc x402 import",
    arg: "<private-key>",
  },
  {
    comment: "# Verify your wallet address",
    command: "mcpc x402 info",
  },
];

const CodeLine: React.FC<{
  block: CommandBlock;
  index: number;
  baseDelay: number;
}> = ({ block, index, baseDelay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();
  const base = width;

  const commentIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay,
    16,
    "GENTLE",
  );
  const cmdIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay + 4,
    16,
    "SNAPPY",
  );

  // Typewriter for command text
  const cmdReveal = springIn(frame, vfps, baseDelay + 4 + index * 16, "LIQUID");
  const fullCmd = block.command + (block.arg ? " " + block.arg : "");
  const visibleChars = Math.floor(
    interpolate(cmdReveal, [0, 1], [0, fullCmd.length + 1], {
      extrapolateRight: "clamp",
    }),
  );
  const visibleCmd = fullCmd.slice(0, visibleChars);

  // Caret blink (only on the last line currently typing, but simple: cursor on the row that's mid-reveal)
  const caretVisible =
    cmdReveal > 0 && cmdReveal < 1 && Math.floor(frame / 6) % 2 === 0;

  // Split visible into command part and arg part for color
  const cmdPartLen = block.command.length;
  const visibleCmdPart = visibleCmd.slice(0, cmdPartLen);
  const visibleArgPart =
    visibleChars > cmdPartLen ? visibleCmd.slice(cmdPartLen) : "";

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: base * 0.006,
        marginBottom: base * 0.026,
      }}
    >
      {/* Comment line */}
      <div
        style={{
          fontFamily:
            "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
          fontSize: base * 0.024,
          color: COLORS.textSubtle,
          opacity: commentIn,
          transform: `translateX(${interpolate(commentIn, [0, 1], [-12, 0])}px)`,
          letterSpacing: "-0.005em",
        }}
      >
        {block.comment}
      </div>

      {/* Command line */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: base * 0.012,
          opacity: cmdIn,
          transform: `translateX(${interpolate(cmdIn, [0, 1], [-16, 0])}px)`,
          fontFamily:
            "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
          fontSize: base * 0.03,
          fontWeight: 600,
          letterSpacing: "-0.005em",
        }}
      >
        <span
          style={{
            color: COLORS.orange,
            fontFamily:
              "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
          }}
        >
          $
        </span>
        <span
          style={{
            color: COLORS.text,
            fontFamily:
              "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
          }}
        >
          {visibleCmdPart}
        </span>
        {visibleArgPart && (
          <span
            style={{
              color: COLORS.orange,
              fontFamily:
                "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
            }}
          >
            {visibleArgPart}
          </span>
        )}
        {caretVisible && (
          <span
            style={{
              display: "inline-block",
              width: base * 0.014,
              height: base * 0.034,
              background: COLORS.orange,
              marginLeft: -base * 0.003,
              fontFamily: "Inter, sans-serif",
            }}
          />
        )}
      </div>
    </div>
  );
};

const CodeScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();
  const base = width;

  const titleIn = springIn(frame, vfps, 0, "SNAPPY");
  const cardIn = springIn(frame, vfps, 3, "LIQUID");

  const cardDrift = ambientDrift(frame, 2, 130, "card-drift");

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg }}>
      <Background />

      {/* Title above card — anchored top-left */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "12%",
          maxWidth: "82%",
        }}
      >
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.textSubtle,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            marginBottom: base * 0.018,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [10, 0])}px)`,
            fontFamily: "Inter, sans-serif",
          }}
        >
          quickstart
        </div>
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: base * 0.072,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.05,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [24, 0])}px)`,
            filter: `blur(${interpolate(titleIn, [0, 1], [6, 0])}px)`,
          }}
        >
          Wallet in{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(3, base * 0.0035)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.012}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              fontFamily: "'GT Walsheim', Inter, sans-serif",
            }}
          >
            one command
          </span>
          .
        </div>
      </div>

      {/* Code card */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          right: "9%",
          top: "32%",
          background: "rgba(255,255,255,0.04)",
          border: `1px solid ${COLORS.border}`,
          borderRadius: base * 0.018,
          padding: `${base * 0.04}px ${base * 0.045}px`,
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [40, cardDrift])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
          filter: `blur(${interpolate(cardIn, [0, 1], [6, 0])}px)`,
          boxShadow: "0 24px 64px rgba(0,0,0,0.4)",
          backdropFilter: "blur(20px)",
        }}
      >
        {/* Terminal chrome header */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: base * 0.01,
            marginBottom: base * 0.032,
            paddingBottom: base * 0.022,
            borderBottom: `1px solid ${COLORS.border}`,
          }}
        >
          <div
            style={{
              width: base * 0.014,
              height: base * 0.014,
              borderRadius: "50%",
              background: COLORS.border,
            }}
          />
          <div
            style={{
              width: base * 0.014,
              height: base * 0.014,
              borderRadius: "50%",
              background: COLORS.border,
            }}
          />
          <div
            style={{
              width: base * 0.014,
              height: base * 0.014,
              borderRadius: "50%",
              background: COLORS.orange,
            }}
          />
          <div
            style={{
              marginLeft: base * 0.014,
              fontFamily:
                "'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace",
              fontSize: base * 0.018,
              color: COLORS.textSubtle,
              letterSpacing: "0.04em",
            }}
          >
            ~/projects/wallet — mcpc
          </div>
        </div>

        {/* Command lines */}
        {COMMANDS.map((block, i) => (
          <CodeLine key={i} block={block} index={i} baseDelay={8} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 3 — Outro: address verified
// ============================================================
const OutroScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();
  const base = width;

  const titleIn = springIn(frame, vfps, 2, "SNAPPY");
  const pillIn = springIn(frame, vfps, 10, "ELASTIC");
  const subIn = springIn(frame, vfps, 16, "GENTLE");

  const driftY = ambientDrift(frame, 2.5, 95, "outro-y");

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg }}>
      <Background />

      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "34%",
          maxWidth: "82%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        {/* Check + label row */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: base * 0.014,
            marginBottom: base * 0.028,
            opacity: pillIn,
            transform: `scale(${interpolate(pillIn, [0, 1], [0.85, 1])})`,
          }}
        >
          <svg
            width={base * 0.034}
            height={base * 0.034}
            viewBox="0 0 24 24"
            style={{ flexShrink: 0 }}
          >
            <circle cx={12} cy={12} r={11} fill={COLORS.orangeTint} />
            <path
              d="M6.5 12.5 L10.5 16.5 L17.5 8.5"
              stroke={COLORS.orange}
              strokeWidth={2.75}
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
          </svg>
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontWeight: 600,
              fontSize: base * 0.024,
              color: COLORS.textSubtle,
              letterSpacing: "0.16em",
              textTransform: "uppercase",
            }}
          >
            ready to sign
          </div>
        </div>

        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: base * 0.082,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.04,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [32, 0])}px)`,
            filter: `blur(${interpolate(titleIn, [0, 1], [6, 0])}px)`,
          }}
        >
          Your wallet is{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(3, base * 0.0035)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.012}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              fontFamily: "'GT Walsheim', Inter, sans-serif",
            }}
          >
            live
          </span>
          .
        </div>

        {/* Sub */}
        <div
          style={{
            marginTop: base * 0.028,
            fontFamily: "Inter, sans-serif",
            fontWeight: 500,
            fontSize: base * 0.026,
            color: COLORS.textMuted,
            lineHeight: 1.35,
            maxWidth: base * 0.6,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [14, 0])}px)`,
          }}
        >
          mcpc handles the keypair. You handle what comes next.
        </div>
      </div>

      {/* Decorative dotted band */}
      <div
        style={{
          position: "absolute",
          right: "-10%",
          bottom: "-10%",
          width: "55%",
          height: "38%",
          background: `radial-gradient(circle at 50% 50%, ${COLORS.orange} 0.6px, transparent 1px)`,
          backgroundSize: "22px 22px",
          opacity: 0.18,
          mixBlendMode: "screen",
        }}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// MAIN COMPOSITION
// ============================================================
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_HEADER + TRANSITION}>
        <HeaderScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_CODE + TRANSITION}>
        <CodeScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_OUTRO}>
        <OutroScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
